use super::*;
#[kani::proof]
fn same_buffers(){let bytes:[u8;688]=kani::any();let candidate_start=0;let proof_start=candidate_start+POOL_V1_PAIR_VERIFIED_AFTERSTATE_BYTES;let candidate_bytes=&bytes[candidate_start..proof_start];assert!(candidate_bytes.len()==688&&core::ptr::eq(candidate_bytes.as_ptr(),unsafe{bytes.as_ptr().add(1)}));}
